WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='INSPECCION_BAJO_BAST' AND v.numero=1),d(t,o) AS (VALUES('DATOS GENERALES',1),('NEUMATICAS',2),('ELECTRICAS',3),('MECANICA',4),('ELECTRONICA',5),('OTROS EQUIPOS INHERENTES AL TREN',6),('RESPONSABLES',7)) INSERT INTO cartillas.secciones(version_id,titulo,orden) SELECT v.id,d.t,d.o FROM v CROSS JOIN d ON CONFLICT(version_id,orden) DO UPDATE SET titulo=EXCLUDED.titulo,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='INSPECCION_BAJO_BAST' AND v.numero=1),s AS (SELECT id,titulo FROM cartillas.secciones WHERE version_id=(SELECT id FROM v)),d(t,c,e,ty,o,cf) AS (VALUES('DATOS GENERALES','actividad','Actividad:','texto',1,'{}'),('DATOS GENERALES','fecha','Fecha:','fecha',2,'{}'),('DATOS GENERALES','pt','PT:','texto',3,'{}'),('DATOS GENERALES','tipo_revision','Tipo de revision:','texto',4,'{"multilinea":true}'),('NEUMATICAS','neumaticas','NEUMATICAS','tabla',1,'{"columnas":[{"codigo":"componente","etiqueta":"COMPONENTE"},{"codigo":"resultado","etiqueta":"SÍ / NO","tipo":"seleccion","opciones":[{"valor":"si","etiqueta":"SÍ"},{"valor":"no","etiqueta":"NO"}]},{"codigo":"tecnico","etiqueta":"TECNICO"},{"codigo":"observaciones","etiqueta":"OBSERVACIONES"}],"filasIniciales":[{"componente":"MANGUERAS NEUMATICAS"},{"componente":"PANELES DE FRENO "},{"componente":"VALVULAS NO PANELIZADAS"},{"componente":"VALVULAS U6"},{"componente":"COMPRESOR AUXILIAR"},{"componente":"CILINDRO DE FRENO"},{"componente":"ZAPATAS DE LIMPIEZA"}]}'),('ELECTRICAS','electricas','ELECTRICAS','tabla',1,'{"columnas":[{"codigo":"componente","etiqueta":"COMPONENTE"},{"codigo":"resultado","etiqueta":"SÍ / NO","tipo":"seleccion","opciones":[{"valor":"si","etiqueta":"SÍ"},{"valor":"no","etiqueta":"NO"}]},{"codigo":"tecnico","etiqueta":"TECNICO"},{"codigo":"observaciones","etiqueta":"OBSERVACIONES"}],"filasIniciales":[{"componente":"CONVERTIDOR ESTATICO"},{"componente":"BATERIAS"},{"componente":"VENTILADORES ONIX"},{"componente":"REACTANCIAS DE FILTRO"},{"componente":"MOTORES DE TRACCION"},{"componente":"CAJONES DE ALTA"},{"componente":"PANTOGRAFO"}]}'),('MECANICA','mecanica','MECANICA','tabla',1,'{"columnas":[{"codigo":"componente","etiqueta":"COMPONENTE"},{"codigo":"resultado","etiqueta":"SÍ / NO","tipo":"seleccion","opciones":[{"valor":"si","etiqueta":"SÍ"},{"valor":"no","etiqueta":"NO"}]},{"codigo":"tecnico","etiqueta":"TECNICO"},{"codigo":"observaciones","etiqueta":"OBSERVACIONES"}],"filasIniciales":[{"componente":"SUSPENSION PRIMARIA"},{"componente":"SUSPENSION SECUNDARIA"},{"componente":"RETORNOS DE CORRIENTE - MASA ,SENSORES , ATP , TACOMETROS"},{"componente":"AMORTIGUADORES"},{"componente":"BIELAS DE TRACCION"},{"componente":"CABLES Y SIRGAS ENTRE COCHES"},{"componente":"COMPRESOR PRINCIPAL"},{"componente":"SECADORES"},{"componente":"BOGIES"}]}'),('ELECTRONICA','electronica','ELECTRONICA','tabla',1,'{"columnas":[{"codigo":"componente","etiqueta":"COMPONENTE"},{"codigo":"resultado","etiqueta":"SÍ / NO","tipo":"seleccion","opciones":[{"valor":"si","etiqueta":"SÍ"},{"valor":"no","etiqueta":"NO"}]},{"codigo":"tecnico","etiqueta":"TECNICO"},{"codigo":"observaciones","etiqueta":"OBSERVACIONES"}],"filasIniciales":[{"componente":"CONVERTIDOR ESTATICO"},{"componente":"ANTENA ATP , JUNTIOX BOX"}]}'),('OTROS EQUIPOS INHERENTES AL TREN','otros_equipos','Otros equipos inherentes al Tren','tabla',1,'{"columnas":[{"codigo":"componente","etiqueta":"COMPONENTE"},{"codigo":"resultado","etiqueta":"SÍ / NO","tipo":"seleccion","opciones":[{"valor":"si","etiqueta":"SÍ"},{"valor":"no","etiqueta":"NO"}]},{"codigo":"tecnico","etiqueta":"TECNICO"},{"codigo":"observaciones","etiqueta":"OBSERVACIONES"}],"filasIniciales":[{"componente":"Otros equipos inherentes al Tren"}]}'),('RESPONSABLES','responsables','RESPONSABLES','tabla',1,'{"columnas":[{"codigo":"responsable","etiqueta":"RESPONSABLE"},{"codigo":"firma","etiqueta":"FIRMA","tipo":"firma"}],"filasIniciales":[{"responsable":"RESPONSABLE 01 :"},{"responsable":"RESPONSABLE 02:"},{"responsable":"RESPONSABLE MTTO :"}]}')) INSERT INTO cartillas.campos(seccion_id,codigo,etiqueta,tipo,orden,configuracion) SELECT s.id,d.c,d.e,d.ty,d.o,d.cf::jsonb FROM d JOIN s ON s.titulo=d.t ON CONFLICT(seccion_id,codigo) DO UPDATE SET configuracion=EXCLUDED.configuracion,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;
